// Storage stays on the original key. New fields are optional for older backups.
const clone=x=>JSON.parse(JSON.stringify(x));
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID();
const blankLog=()=>({kg:'',reps:'',done:false});
const DAYS=['Sin día fijo','Lunes','Martes','Miércoles','Jueves','Viernes','Sábado','Domingo'];
const GROUPS={'press-maquina':'Pecho','press-inclinado':'Pecho',jalon:'Espalda','remo-polea':'Espalda','remo-apoyado':'Espalda',laterales:'Hombros',hombro:'Hombros',curl:'Brazos',triceps:'Brazos',prensa:'Piernas',rumano:'Piernas',extension:'Piernas',femoral:'Piernas',gemelos:'Piernas',goblet:'Piernas','hip-thrust':'Piernas',crunch:'Abdomen'};
const textOK=(s,max=200)=>typeof s==='string'&&s.length<=max;
const idOK=s=>textOK(s,200)&&s.length>0;
const integer=(n,min,max)=>Number.isInteger(n)&&n>=min&&n<=max;
function validExercise(e){return e&&idOK(e.id)&&textOK(e.name)&&e.name.trim().length>0&&integer(e.sets,1,10)&&integer(e.min,1,50)&&integer(e.max,e.min,50)&&Number.isFinite(e.rest)&&e.rest>=15&&e.rest<=600&&textOK(e.cue,3000)&&textOK(e.alt,1000)&&(e.guideId===undefined||textOK(e.guideId))&&(e.slotId===undefined||idOK(e.slotId))&&(e.noteSnapshot===undefined||textOK(e.noteSnapshot,1000));}
function validLog(l){return l&&typeof l.done==='boolean'&&(l.kg===''||Number.isFinite(l.kg)&&l.kg>=0&&l.kg<=2000)&&(l.reps===''||integer(l.reps,1,200))&&(!l.done||(l.kg!==''&&l.reps!==''));}
function validSession(s){return s&&idOK(s.id)&&idOK(s.routineId)&&textOK(s.name)&&Number.isFinite(s.started)&&(s.finished===undefined||Number.isFinite(s.finished))&&Array.isArray(s.exercises)&&s.exercises.length>0&&s.exercises.length<=60&&s.exercises.every(e=>validExercise(e)&&Array.isArray(e.logs)&&e.logs.length>0&&e.logs.length<=15&&e.logs.every(validLog))&&(s.focusIndex===undefined||integer(s.focusIndex,0,59));}
function validRoutines(rs){return Array.isArray(rs)&&rs.length<=20&&rs.every(r=>r&&idOK(r.id)&&textOK(r.name)&&r.name.trim()&&textOK(r.focus)&&textOK(r.day)&&Array.isArray(r.exercises)&&r.exercises.length<=30&&r.exercises.every(validExercise))&&new Set(rs.map(r=>r.id)).size===rs.length;}
function validSavedPlan(p){return p&&idOK(p.id)&&textOK(p.name)&&Number.isFinite(p.savedAt)&&integer(p.weeklyGoal,1,7)&&(p.planDays===null||integer(p.planDays,1,6))&&validRoutines(p.routines);}
function buildTrainingPlan(days,slots=true){
 const template=window.GYM_TRAINING_PLANS[days];if(!template)return null;
 const catalog=new Map();DEFAULT.forEach(r=>r.exercises.forEach(e=>{if(!catalog.has(e.id))catalog.set(e.id,e);}));
 return template.sessions.map(spec=>{
   const r=spec.from?clone(DEFAULT.find(r=>r.id===spec.from)):{id:spec.id,name:spec.name,day:spec.day,focus:spec.focus,exercises:spec.exercises.map(([id,sets])=>({...clone(catalog.get(id)),sets}))};
   r.optional=false;delete r.time;r.exercises.forEach(e=>{if(slots)e.slotId=uid();else delete e.slotId;});return r;
 });
}
// Ignore slot identifiers and historical metadata, but detect edits to any plan content.
function planSignature(rs){return JSON.stringify(rs.map(r=>({id:r.id,name:r.name,focus:r.focus,day:r.day,optional:!!r.optional,exercises:r.exercises.map(e=>({id:e.id,name:e.name,sets:e.sets,min:e.min,max:e.max,rest:e.rest,cue:e.cue,alt:e.alt,guideId:e.guideId??e.id}))})));}
function matchingTemplateDays(rs){const signature=planSignature(rs);return [1,2,3,4,5,6].find(n=>signature===planSignature(buildTrainingPlan(n,false)))||null;}
function isUneditedLegacyPlan(rs){return planSignature(rs)===planSignature(DEFAULT);}
function currentPlanSnapshot(){
 if(!state.routines.length||matchingTemplateDays(state.routines)||isUneditedLegacyPlan(state.routines))return null;
 if(state.savedPlans.some(p=>planSignature(p.routines)===planSignature(state.routines)&&p.weeklyGoal===state.settings.weeklyGoal))return null;
 return {id:uid(),name:`Plan personalizado · ${state.routines.length} ${state.routines.length===1?'día':'días'}`,savedAt:Date.now(),weeklyGoal:state.settings.weeklyGoal,planDays:state.settings.planDays??null,routines:clone(state.routines)};
}
function applyTrainingDays(n){
 if(!integer(n,1,6))return false;const snapshot=currentPlanSnapshot();
 if(snapshot&&state.savedPlans.length>=20){toast('Tienes 20 planes guardados. Elimina una copia que no necesites antes de aplicar otra rutina.');return false;}
 const same=matchingTemplateDays(state.routines)===n;
 if(!commit(()=>{if(snapshot)state.savedPlans.unshift(snapshot);if(!same)state.routines=buildTrainingPlan(n);Object.assign(state.settings,{weeklyGoal:n,planDays:n,planRevision:1});}))return false;
 selected=nextRoutine();close();go('rutina');toast(`Rutina de ${n} ${n===1?'día':'días'} aplicada.${snapshot?' Tu plan personalizado queda guardado.':''}`);return true;
}
function showGoal(){
 const days=Math.max(1,Math.min(6,state.settings.weeklyGoal));
 modal(`<h2>Días de entrenamiento</h2><form id="goal-form"><label for="weekly-goal">¿Cuántos días entrenarás por semana?</label><select name="goal" id="weekly-goal">${[1,2,3,4,5,6].map(n=>`<option value="${n}" ${n===days?'selected':''}>${n} ${n===1?'día':'días'}</option>`).join('')}</select>${state.settings.weeklyGoal===7?'<p class="note">Tu ajuste anterior de 7 sesiones se conserva hasta que apliques otro. Los planes automáticos dejan al menos un día de descanso.</p>':''}<div id="plan-preview" aria-live="polite"></div><p class="note">Al aplicar se actualizan la rutina completa y el objetivo semanal. Tus pesos, notas e historial se conservan.${state.active?' El entrenamiento en curso continúa como lo empezaste.':''}</p>${currentPlanSnapshot()?'<p class="plan-preserve">Tu rutina personalizada se guardará en «Planes anteriores» para poder recuperarla.</p>':''}<div class="actions"><button type="button" class="btn secondary" data-action="close">Cancelar</button><button class="btn" id="apply-days" type="submit">Aplicar rutina</button></div></form>`);
 renderPlanPreview(days);
}
function renderPlanPreview(n){
 const plan=buildTrainingPlan(n,false),template=window.GYM_TRAINING_PLANS[n];if(!plan||!$('#plan-preview'))return;
 const count=plan.reduce((sum,r)=>sum+r.exercises.reduce((s,e)=>s+e.sets,0),0),days=new Set(plan.map(r=>r.day)),rest=DAYS.slice(1).filter(d=>!days.has(d));
 $('#plan-preview').innerHTML=`<div class="plan-preview-head"><p class="eyebrow">${n} ${n===1?'SESIÓN':'SESIONES'} · ${count} SERIES DE TRABAJO / SEMANA</p><h3>${esc(template.title)}</h3><p class="note">${esc(template.description)}</p></div><div class="plan-preview-days">${plan.map(r=>`<details><summary><span><strong>${esc(r.day)} · ${esc(r.name)}</strong><small>${r.exercises.length} ejercicios · ${r.exercises.reduce((s,e)=>s+e.sets,0)} series</small></span></summary><ul>${r.exercises.map(e=>`<li>${esc(e.name)} <span>${e.sets} × ${e.min}–${e.max}</span></li>`).join('')}</ul></details>`).join('')}</div><p class="note"><strong>Descanso:</strong> ${rest.join(', ')}. Puedes mover los días manteniendo la recuperación.</p><p class="note">Plan general editable. Si estás empezando, usa el modo de adaptación y elige una frecuencia que puedas mantener.</p>`;
 $('#apply-days').textContent=`Aplicar rutina de ${n} ${n===1?'día':'días'}`;
}
function renderPlanOverview(){
 const n=matchingTemplateDays(state.routines),scheduled=state.routines.filter(r=>r.exercises.length&&!r.optional).length;
 return `<section class="plan-overview"><div><p class="eyebrow">${n?'PLAN ADAPTADO A TUS DÍAS':'PLAN PERSONALIZADO'}</p><h2>${n?esc(window.GYM_TRAINING_PLANS[n].title):'Tu distribución de entrenamiento'}</h2><p>${scheduled} ${scheduled===1?'sesión':'sesiones'} en el plan · objetivo de ${state.settings.weeklyGoal} por semana</p>${scheduled!==state.settings.weeklyGoal?'<p class="plan-mismatch">Tu distribución actual no coincide con el objetivo. Puedes adaptarla desde «Días y rutina».</p>':''}</div><button class="btn secondary" data-action="goal">Días y rutina</button></section>`;
}
function renderSavedPlans(){return state.savedPlans.length?`<section class="card"><h2>Planes anteriores</h2><p class="note">Tus rutinas personalizadas se conservan aquí cuando aplicas un plan por días.</p>${state.savedPlans.map((p,i)=>`<div class="saved-plan"><strong>${esc(p.name)}</strong><p class="small muted">${fmtDate(p.savedAt)} · objetivo ${p.weeklyGoal} / semana</p><div class="actions"><button class="btn secondary" data-action="restoreplan" data-index="${i}">Recuperar</button><button class="textbtn" data-action="deleteplan" data-id="${esc(p.id)}">Eliminar copia</button></div></div>`).join('')}</section>`:'';}
function restoreSavedPlan(id){
 const saved=state.savedPlans.find(p=>p.id===id);if(!saved)return false;const snapshot=currentPlanSnapshot();
 if(snapshot&&state.savedPlans.length>=20){toast('Elimina una copia que no necesites para poder guardar tu plan actual.');return false;}
 if(!commit(()=>{if(snapshot)state.savedPlans.unshift(snapshot);state.routines=clone(saved.routines);Object.assign(state.settings,{weeklyGoal:saved.weeklyGoal,planDays:saved.planDays,planRevision:1});}))return false;
 selected=nextRoutine();close();go('rutina');toast('Plan recuperado. Tu historial se conserva.');return true;
}

function validState(s){return s&&s.version===1&&validRoutines(s.routines)&&Array.isArray(s.history)&&s.history.every(h=>validSession(h)&&Number.isFinite(h.finished))&&(s.active===null||validSession(s.active))&&(s.timerEnd===null||Number.isFinite(s.timerEnd))&&(s.settings===undefined||(s.settings&&integer(s.settings.weeklyGoal,1,7)&&['focus','list'].includes(s.settings.trainingMode)&&(s.settings.planRevision===undefined||s.settings.planRevision===1)&&(s.settings.planDays===undefined||s.settings.planDays===null||integer(s.settings.planDays,1,6))))&&(s.machineNotes===undefined||(Array.isArray(s.machineNotes)&&s.machineNotes.length<=3000&&s.machineNotes.every(n=>n&&idOK(n.id)&&textOK(n.text,1000))))&&(s.savedPlans===undefined||(Array.isArray(s.savedPlans)&&s.savedPlans.length<=20&&s.savedPlans.every(validSavedPlan)&&new Set(s.savedPlans.map(p=>p.id)).size===s.savedPlans.length));}
function normalizeState(data){
  const s=clone(data);
  s.settings=s.settings||{weeklyGoal:4,trainingMode:'focus'};
  s.machineNotes=s.machineNotes||[];
  s.savedPlans=s.savedPlans||[];
  s.savedPlans.forEach(p=>p.routines.forEach(r=>{const seen=new Set();r.exercises.forEach(e=>{if(!e.slotId||seen.has(e.slotId))e.slotId=uid();seen.add(e.slotId);});}));
  s.routines.forEach(r=>{const slots=new Set();r.exercises.forEach(e=>{if(!e.slotId||slots.has(e.slotId))e.slotId=uid();slots.add(e.slotId);});});
  if(s.active){
    const r=s.routines.find(r=>r.id===s.active.routineId);
    s.active.exercises.forEach((e,i)=>{if(!e.slotId&&r?.exercises[i]?.id===e.id)e.slotId=r.exercises[i].slotId;e.originExerciseId=e.originExerciseId||e.id;});
    s.active.focusIndex=Math.min(s.active.focusIndex||0,s.active.exercises.length-1);
  }
  // Repair the previous fixed default plan only when it has not been personalized.
  // Active sessions were linked above; their exercises and completed logs stay untouched.
  if(s.settings.planRevision!==1){
    if(integer(s.settings.weeklyGoal,1,6)&&(isUneditedLegacyPlan(s.routines)||matchingTemplateDays(s.routines))){s.routines=buildTrainingPlan(s.settings.weeklyGoal);s.settings.planDays=s.settings.weeklyGoal;}
    else s.settings.planDays=matchingTemplateDays(s.routines);
    s.settings.planRevision=1;
  }
  s.history.sort((a,b)=>b.finished-a.finished);
  return s;
}
const freshState=()=>normalizeState({version:1,routines:clone(DEFAULT),history:[],active:null,timerEnd:null});
let state=freshState(),loadError=false;
try{const raw=localStorage.getItem(KEY);if(raw){const data=JSON.parse(raw);if(!validState(data))throw Error('Invalid backup');state=normalizeState(data);}}catch{loadError=true;}
let selected=state.active?.routineId||nextRoutine(),view='entrenar',progressId='press-maquina',toastTimeout;
let editing=null,routineEditing=null,picker=null,pendingRemove=null,pendingDelete='',noteEditing=null,imported=null,pendingPlanId='',pendingPlanDelete='';
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('#toast').style.display='none',4500);}
function save(){if(loadError){toast('Revisa tus datos en Rutina antes de guardar cambios.');return false;}try{localStorage.setItem(KEY,JSON.stringify(state));return true;}catch{toast('No se pudo guardar. Exporta una copia desde Rutina.');return false;}}
// Apply edits atomically: a storage failure never leaves a false "saved" state.
function commit(change){if(loadError){toast('Revisa tus datos en Rutina antes de hacer cambios.');return false;}const before=clone(state);change();if(save())return true;state=before;return false;}
function dateKey(n){const d=new Date(n);return `${d.getFullYear()}-${d.getMonth()}-${d.getDate()}`;}
function fmtDate(n){return new Date(n).toLocaleDateString('es-ES',{day:'numeric',month:'short'});}
function num(n){return Number(n).toLocaleString('es-ES',{maximumFractionDigits:2});}
function nextRoutine(){let rs=state.routines.filter(r=>!r.optional&&r.exercises.length);if(!rs.length)rs=state.routines.filter(r=>r.exercises.length);if(!rs.length)return state.routines[0]?.id||'';const last=state.history.find(s=>rs.some(r=>r.id===s.routineId));return rs[(rs.findIndex(r=>r.id===last?.routineId)+1)%rs.length].id;}
function lastFor(id){for(const s of state.history){const es=s.exercises.filter(e=>e.id===id);const logs=es.flatMap(e=>e.logs.filter(l=>l.done));if(logs.length)return {...es[0],logs,date:s.finished};}return null;}
function completed(s){return s.exercises.reduce((n,e)=>n+e.logs.filter(l=>l.done).length,0);}
function volume(s){return s.exercises.reduce((n,e)=>n+e.logs.filter(l=>l.done).reduce((v,l)=>v+l.kg*l.reps,0),0);}
function noteFor(id){return state.machineNotes.find(n=>n.id===id)?.text||'';}
function putNote(id,text){state.machineNotes=state.machineNotes.filter(n=>n.id!==id);if(text)state.machineNotes.push({id,text});}
function exerciseCatalog(){const map=new Map();DEFAULT.forEach(r=>r.exercises.forEach(e=>{if(!map.has(e.id))map.set(e.id,e);}));state.savedPlans.forEach(p=>p.routines.forEach(r=>r.exercises.forEach(e=>map.set(e.id,e))));[...state.history].reverse().forEach(s=>s.exercises.forEach(e=>map.set(e.id,e)));state.routines.forEach(r=>r.exercises.forEach(e=>map.set(e.id,e)));state.active?.exercises.forEach(e=>map.set(e.id,e));return [...map.values()].map(e=>({id:e.id,name:e.name,sets:e.sets,min:e.min,max:e.max,rest:e.rest,cue:e.cue,alt:e.alt,...(e.guideId!==undefined?{guideId:e.guideId}:{})}));}
function groupFor(e){return GROUPS[e.guideId||e.id]||'Personalizados';}
function weeklyStats(now=Date.now()){const start=new Date(now);start.setHours(0,0,0,0);start.setDate(start.getDate()-(start.getDay()+6)%7);const end=new Date(start);end.setDate(end.getDate()+7);return {start,sessions:state.history.filter(s=>s.finished>=+start&&s.finished<+end&&s.finished<=now)};}
function recordsFor(session,earlier=state.history.filter(s=>s.id!==session.id&&s.finished<session.finished)){
  const result=[],ids=[...new Set(session.exercises.map(e=>e.id))];
  for(const id of ids){const es=session.exercises.filter(e=>e.id===id),logs=es.flatMap(e=>e.logs.filter(l=>l.done)),past=earlier.flatMap(s=>s.exercises.filter(e=>e.id===id).flatMap(e=>e.logs.filter(l=>l.done)));if(!logs.length||!past.length)continue;
    const max=Math.max(...logs.map(l=>l.kg)),previous=Math.max(...past.map(l=>l.kg));
    if(max>previous)result.push({id,name:es[0].name,type:'weight',kg:max,reps:Math.max(...logs.filter(l=>l.kg===max).map(l=>l.reps)),previous});
    const sameWeight=[...new Set(logs.map(l=>l.kg))].sort((a,b)=>b-a).find(kg=>past.some(l=>l.kg===kg)&&Math.max(...logs.filter(l=>l.kg===kg).map(l=>l.reps))>Math.max(...past.filter(l=>l.kg===kg).map(l=>l.reps)));
    if(sameWeight!==undefined)result.push({id,name:es[0].name,type:'reps',kg:sameWeight,reps:Math.max(...logs.filter(l=>l.kg===sameWeight).map(l=>l.reps)),previous:Math.max(...past.filter(l=>l.kg===sameWeight).map(l=>l.reps))});
  }return result;
}
function recordText(r){return r.type==='weight'?`${num(r.kg)} kg · antes ${num(r.previous)} kg`:`${r.reps} reps con ${num(r.kg)} kg · antes ${r.previous} reps`;}
function recordCards(records){return records.map(r=>`<div class="record"><span class="record-symbol" aria-hidden="true">★</span><div><strong>${esc(r.name)}</strong><p>${r.type==='weight'?'Nuevo máximo de peso':'Más repeticiones con el mismo peso'}</p><span>${recordText(r)}</span></div></div>`).join('');}
function renderWeek(){const {start,sessions}=weeklyStats(),goal=state.settings.weeklyGoal;return `<section class="card"><div class="section-title"><h2>Tu semana</h2><button class="textbtn" data-action="goal">Días y rutina</button></div><div class="goal-line"><strong>${sessions.length}<span> / ${goal}</span></strong><span>${sessions.length>=goal?'Objetivo completado':'sesiones completadas'}</span></div><div class="goal-track" role="progressbar" aria-label="Objetivo semanal" aria-valuemin="0" aria-valuemax="${goal}" aria-valuenow="${Math.min(sessions.length,goal)}"><i style="width:${Math.min(100,sessions.length/goal*100)}%"></i></div><div class="week">${['L','M','X','J','V','S','D'].map((d,i)=>{const date=new Date(start);date.setDate(start.getDate()+i);const done=sessions.some(s=>dateKey(s.finished)===dateKey(date)),planned=state.routines.some(r=>r.day===DAYS[i+1]&&r.exercises.length&&!r.optional);return `<div class="week-day ${planned?'planned':''} ${done?'done':''} ${dateKey(date)===dateKey(Date.now())?'today':''}" aria-label="${date.toLocaleDateString('es-ES')} ${done?'sesión registrada':planned?'entrenamiento planificado':''}">${d}<span>${done?'✓':date.getDate()}</span></div>`;}).join('')}</div><p class="small muted">${sessions.reduce((n,s)=>n+completed(s),0)} series esta semana · ${state.history.length} sesiones en total</p></section>`;}
function icon(n){const paths={entrenar:'M6 5v14M3 8v8M18 5v14M21 8v8M6 12h12',rutina:'M8 4h12v17H4V4h4M8 3h8v4H8zM8 12h8M8 16h6',historial:'M4 5v5h5M4 10a8 8 0 1 1 1 8M12 8v5l3 2',progreso:'M4 4v16h16M7 15l4-5 4 2 5-7'};return `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]}"/></svg>`;}
function getGuide(e){const id=Object.prototype.hasOwnProperty.call(e,'guideId')?e.guideId:e.id;return typeof id==='string'&&Object.prototype.hasOwnProperty.call(window.GYM_GUIDES,id)?window.GYM_GUIDES[id]:null;}
function guideButton(e,ei){const g=getGuide(e);return g?`<button class="guide-trigger" data-action="guide" data-ex="${ei}" aria-label="Ver músculos y movimiento de ${esc(e.name)}"><span class="guide-thumb"><img src="./assets/exercises/${g.art}-1.svg" alt="" width="65" height="65" loading="lazy"></span><span><strong>Músculos y movimiento</strong><small>${esc(g.primary.join(' · '))}</small></span><span class="guide-open" aria-hidden="true">↗</span></button>`:'<p class="guide-unavailable">Sin guía visual asignada. Puedes elegirla al editar el ejercicio en Rutina.</p>';}
let guideExercise=null,guideTab='muscles';
function muscleSvg(g,face){return `<svg viewBox="0 0 1000 2000" role="img" aria-label="${face==='anterior'?'Vista frontal':'Vista posterior'}: músculos principales en rosa y secundarios en ámbar">${window.GYM_BODY_MAP[face].map(part=>part.points.map(points=>`<polygon points="${points}" fill="${g.main.includes(part.muscle)?'#e75b75':g.support.includes(part.muscle)?'#eab253':'#cbd3da'}"/>`).join('')).join('')}</svg>`;}
function guideContent(){const e=guideExercise,g=getGuide(e);return `<div class="guide-titlebar"><div><p class="eyebrow">GUÍA DEL EJERCICIO</p><h2 id="guide-title">${esc(e.name)}</h2></div><button class="textbtn" data-action="close" aria-label="Cerrar guía">Cerrar ✕</button></div><div class="guide-tabs" role="tablist" aria-label="Guía del ejercicio"><button id="guide-muscles-tab" type="button" role="tab" aria-selected="${guideTab==='muscles'}" tabindex="${guideTab==='muscles'?0:-1}" aria-controls="guide-muscles-panel" data-action="guidetab" data-tab="muscles">Músculos</button><button id="guide-movement-tab" type="button" role="tab" aria-selected="${guideTab==='movement'}" tabindex="${guideTab==='movement'?0:-1}" aria-controls="guide-movement-panel" data-action="guidetab" data-tab="movement">Movimiento</button></div><div id="guide-muscles-panel" role="tabpanel" aria-labelledby="guide-muscles-tab" ${guideTab!=='muscles'?'hidden':''}><div class="guide-maps"><figure>${muscleSvg(g,'anterior')}<figcaption>Delante</figcaption></figure><figure>${muscleSvg(g,'posterior')}<figcaption>Detrás</figcaption></figure></div><div class="muscle-key"><span><i></i>Principales</span><span><i class="support"></i>Secundarios / apoyo</span></div><div class="guide-muscle-tags">${g.primary.map(m=>`<span>Principal · ${esc(m)}</span>`).join('')}${g.secondary.map(m=>`<span class="secondary">Apoyo · ${esc(m)}</span>`).join('')}</div><p class="guide-note">Mapa de zonas musculares orientativo. No representa porcentajes de activación ni todos los músculos estabilizadores.${g.note?' '+esc(g.note):''}</p></div><div id="guide-movement-panel" role="tabpanel" aria-labelledby="guide-movement-tab" ${guideTab!=='movement'?'hidden':''}><div class="guide-poses ${g.frames===1?'single-pose':''}">${Array.from({length:g.frames||2},(_,i)=>i+1).map(i=>`<figure><img src="./assets/exercises/${g.art}-${i}.svg" alt="${esc(g.title)}, posición ${i}" width="512" height="512"><figcaption>${g.frames===1?'Referencia del ejercicio':'Posición '+i}</figcaption></figure>`).join('')}</div>${g.note?`<p class="guide-note">${esc(g.note)}</p>`:''}<p class="guide-note">${g.frames===1?'Ilustración de referencia; no muestra toda la secuencia.':'Dos posiciones de referencia; realiza todo el recorrido de forma controlada.'}</p></div><div class="guide-technique"><h3>Claves de técnica</h3><p>${esc(e.cue)}</p><p style="margin-top:8px"><strong>Alternativa:</strong> ${esc(e.alt)}.</p></div><p class="guide-credit"><a href="./assets/licenses/credits.html" target="_blank" rel="noopener">Créditos de las ilustraciones y mapas</a></p>`;}
function changeGuideTab(tab){guideTab=tab==='movement'?'movement':'muscles';$('#modal-body').innerHTML=guideContent();document.getElementById('guide-'+guideTab+'-tab').focus();}
function showGuide(e){if(!getGuide(e))return;guideExercise=e;guideTab='muscles';modal(guideContent());$('#modal').classList.add('guide-dialog');$('#modal').setAttribute('aria-labelledby','guide-title');}
function render(){view=location.hash.slice(1)||'entrenar';if(!['entrenar','rutina','historial','progreso'].includes(view))view='entrenar';document.body.classList.toggle('focus-workout',view==='entrenar'&&!!state.active&&state.settings.trainingMode==='focus');$('#nav').innerHTML=['entrenar','rutina','historial','progreso'].map((v,i)=>`<a href="#${v}" class="${v===view?'active':''}" ${v===view?'aria-current="page"':''}>${icon(v)}${['Entrenar','Rutina','Historial','Progreso'][i]}</a>`).join('');$('#app').innerHTML=(loadError?'<div class="data-error" role="alert">No se han podido leer tus datos. Exporta la copia original desde Rutina antes de reiniciar.</div>':'')+({entrenar:renderTrain,rutina:renderPlan,historial:renderHistory,progreso:renderProgress}[view])();renderTimer();}
function pagehead(eyebrow,title,side=''){return `<div class="pagehead"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1></div>${side}</div>`;}
function go(hash){location.hash=hash;render();window.scrollTo(0,0);}
function renderTrain(){
 if(state.active)return renderSession();
 const r=state.routines.find(r=>r.id===selected)||state.routines[0];
 const hero=r?`<section class="hero"><p class="eyebrow">${state.history.length?'SIGUIENTE SESIÓN':'TU PRIMERA SESIÓN'}</p><div class="hero-row"><div><h2>${esc(r.name)}</h2><p class="muted" style="margin-top:8px">${esc(r.focus)}</p><p class="small" style="margin-top:18px">${r.exercises.length} ejercicios · ${esc(r.day)}</p></div><div class="daynumber">${String(state.routines.indexOf(r)+1).padStart(2,'0')}</div></div>${r.exercises.length?`<button class="btn lime full" data-action="start" data-id="${esc(r.id)}">Empezar entrenamiento</button>`:'<a href="#rutina" class="btn lime full">Añadir ejercicios</a>'}</section>`:`<section class="hero"><h2>Tu plan empieza aquí.</h2><p class="muted">Crea un día y añade los ejercicios que quieras entrenar.</p><button class="btn lime full" data-action="newroutine">Crear mi primera rutina</button></section>`;
 return pagehead('TU ESPACIO DE ENTRENAMIENTO','A tu ritmo.')+renderPlanOverview()+`<div class="grid"><div class="stack">${hero}${renderWeek()}<div class="tip"><h3>Entrena con margen</h3><p class="small muted">Prioriza una técnica cómoda y controlada. Descansa cuando lo necesites; el objetivo semanal es una referencia.</p></div></div><section class="card"><div class="section-title"><h2>Elige tu sesión</h2><a href="#rutina" class="textbtn">Editar rutinas</a></div>${state.routines.map((r,i)=>`<button class="routine ${selected===r.id?'chosen':''}" data-action="select" data-id="${esc(r.id)}"><span class="num">${String(i+1).padStart(2,'0')}</span><span class="grow"><strong>${esc(r.name)}</strong><span class="small muted">${esc(r.day)}${r.optional?' · Opcional':''} · ${r.exercises.length} ejercicios</span></span></button>`).join('')||'<p class="note">Aquí aparecerán tus días de entrenamiento.</p>'}<button class="textbtn" data-action="newroutine" style="margin-top:16px">+ Crear otro día</button></section></div>`;
}
function renderExercise(e,ei,focused){const prev=lastFor(e.id),g=getGuide(e),note=noteFor(e.id),done=e.logs.filter(l=>l.done).length;return `<article class="exercise ${focused?'focused-exercise':''}"><div class="exercise-head"><div><p class="exercise-index">EJERCICIO ${ei+1} DE ${state.active.exercises.length}${e.retained?' · SERIES CONSERVADAS':''}</p><h2>${esc(e.name)}</h2><p class="small muted">${e.min}–${e.max} reps · ${e.rest} s de descanso</p></div></div>${focused&&g?`<button class="focus-illustration" data-action="guide" data-ex="${ei}" aria-label="Ver guía de ${esc(e.name)}"><img src="./assets/exercises/${g.art}-1.svg" alt="Ilustración de ${esc(e.name)}" width="200" height="200"><span>Ver músculos y técnica</span></button>`:guideButton(e,ei)}${e.swappedFrom?`<p class="note">Sustituye a ${esc(e.swappedFrom)}.</p>`:''}<div class="previous">${prev?`Última vez · ${fmtDate(prev.date)}: ${prev.logs.map(l=>`${num(l.kg)} kg × ${l.reps}`).join(' / ')}`:'Todavía no hay marcas de este ejercicio.'}</div><div class="machine-note"><div class="section-title"><strong>Ajustes de la máquina</strong><button class="textbtn" data-action="notes" data-id="${esc(e.id)}">${note?'Editar':'Añadir nota'}</button></div><p>${note?esc(note):'Guarda el asiento, el agarre o cualquier ajuste que quieras recordar.'}</p></div><div class="set labels"><span>Serie</span><span style="text-align:center">Peso · kg</span><span style="text-align:center">Reps</span><span class="sr-only">Hecha</span></div>${e.logs.map((l,li)=>{const p=prev?.logs[li];return `<div class="set ${l.done?'done':''}"><span class="small muted">${li+1}</span><input aria-label="${esc(e.name)} serie ${li+1} peso en kg" type="number" inputmode="decimal" min="0" max="2000" step="any" data-ex="${ei}" data-set="${li}" data-field="kg" value="${l.kg}" placeholder="${p?.kg??'—'}"><input aria-label="${esc(e.name)} serie ${li+1} repeticiones" type="number" inputmode="numeric" min="1" max="200" step="1" data-ex="${ei}" data-set="${li}" data-field="reps" value="${l.reps}" placeholder="${p?.reps??e.min}"><button aria-label="${l.done?'Desmarcar':'Completar'} serie ${li+1} de ${esc(e.name)}" aria-pressed="${l.done}" data-action="check" data-ex="${ei}" data-set="${li}">${l.done?'✓':'○'}</button></div>`;}).join('')}<p class="exercise-count small muted" data-count="${ei}">${done} / ${e.logs.length} series completadas</p><div class="actions"><button class="textbtn" data-action="addset" data-ex="${ei}" ${e.logs.length>=15||e.retained?'disabled':''}>+ Añadir serie</button><button class="textbtn" data-action="removeset" data-ex="${ei}" ${e.logs.length<=1||e.retained?'disabled':''}>Quitar última</button></div><div class="exercise-tools"><button class="btn secondary" data-action="rest" data-seconds="${e.rest}">Descansar · ${e.rest} s</button><button class="btn secondary" data-action="replace" data-ex="${ei}" ${e.retained||done===e.logs.length?'disabled':''}>Cambiar ejercicio</button></div><details class="help"><summary>Técnica y alternativa</summary><p>${esc(e.cue)} Alternativa: ${esc(e.alt)}.</p></details></article>`;}
function renderSession(){const s=state.active,total=s.exercises.reduce((n,e)=>n+e.logs.length,0),done=completed(s),focused=state.settings.trainingMode==='focus',index=Math.min(s.focusIndex||0,s.exercises.length-1);return pagehead('ENTRENAMIENTO EN CURSO',esc(s.name),'<button class="textbtn" data-action="cancel">Descartar</button>')+`<div class="sessionbar"><div style="flex:1"><strong id="session-count">${done} / ${total} series</strong><p>Marca cada serie cuando la termines</p><div class="progress-track"><i id="session-progress" style="width:${done/total*100}%"></i></div></div><button class="btn lime" data-action="finish">Terminar</button></div><div class="session-toolbar"><div class="mode-switch" role="group" aria-label="Vista del entrenamiento"><button data-action="mode" data-mode="focus" aria-pressed="${focused}">Un ejercicio</button><button data-action="mode" data-mode="list" aria-pressed="${!focused}">Lista completa</button></div><label class="sr-only" for="session-jump">Ir al ejercicio</label><select id="session-jump"><option value="">Ir a un ejercicio…</option>${s.exercises.map((e,i)=>`<option value="${i}">${i+1}. ${esc(e.name)}${e.logs.every(l=>l.done)?' ✓':''}</option>`).join('')}</select></div><div class="${focused?'focus-layout':'exlist'}">${focused?`${renderExercise(s.exercises[index],index,true)}<aside class="focus-side"><div id="focus-timer"></div><div class="card next-exercise"><p class="eyebrow">${index===s.exercises.length-1?'ÚLTIMO EJERCICIO':'A CONTINUACIÓN'}</p><h3>${index===s.exercises.length-1?'Revisa y guarda tu sesión':esc(s.exercises[index+1].name)}</h3><div class="actions"><button class="btn secondary" data-action="navigate" data-index="${index-1}" ${index===0?'disabled':''}>Anterior</button>${index<s.exercises.length-1?`<button class="btn lime" data-action="navigate" data-index="${index+1}">Siguiente</button>`:'<button class="btn lime" data-action="finish">Terminar</button>'}</div><p class="note">Puedes avanzar sin completar todas las series. Solo se guardarán las que marques.</p></div></aside>`:s.exercises.map((e,i)=>renderExercise(e,i,false)).join('')}</div><p class="note">Mancuernas: kg de una mancuerna. Barra: kg totales. Máquina: carga indicada. Las marcas se comparan dentro de cada ejercicio.</p>`;}
function renderPlan(){return pagehead('TU PLAN, A TU MEDIDA','Tus rutinas.',`<button class="btn lime" data-action="newroutine">+ Crear día</button>`)+renderPlanOverview()+`<div class="grid"><div class="stack">${state.routines.map((r,ri)=>`<section class="card" id="routine-${ri}"><div class="section-title"><div><p class="eyebrow">${esc(r.day)}${r.optional?' · OPCIONAL':''}</p><h2>${esc(r.name)}</h2><p class="small muted">${esc(r.focus)}</p></div><button class="textbtn" data-action="editroutine" data-ri="${ri}">Editar día</button></div><div class="routine-tools"><button class="textbtn" data-action="moveroutine" data-ri="${ri}" data-delta="-1" aria-label="Subir ${esc(r.name)}" ${ri===0?'disabled':''}>↑ Subir</button><button class="textbtn" data-action="moveroutine" data-ri="${ri}" data-delta="1" aria-label="Bajar ${esc(r.name)}" ${ri===state.routines.length-1?'disabled':''}>↓ Bajar</button><button class="textbtn" data-action="selectplan" data-id="${esc(r.id)}" ${!r.exercises.length?'disabled':''}>Entrenar</button></div>${r.exercises.map((e,ei)=>{const g=getGuide(e);return `<div class="plan-exercise"><div class="routine guide-plan-row">${g?`<button class="exercise-thumb" data-action="guide" data-ri="${ri}" data-ei="${ei}" aria-label="Ver músculos de ${esc(e.name)}"><img src="./assets/exercises/${g.art}-1.svg" alt="" width="62" height="62" loading="lazy"></button>`:'<span class="custom-exercise-icon" aria-hidden="true">'+(ei+1)+'</span>'}<span class="grow"><strong>${esc(e.name)}</strong><span class="small muted">${e.sets} × ${e.min}–${e.max} · ${e.rest} s</span>${g?`<span class="muscle-caption">${esc(g.primary.join(' · '))}</span>`:''}</span><button class="textbtn" data-action="edit" data-ri="${ri}" data-ei="${ei}" aria-label="Editar ${esc(e.name)}">Editar</button></div>${noteFor(e.id)?`<p class="plan-note">${esc(noteFor(e.id))}</p>`:''}<div class="plan-exercise-tools"><button class="textbtn" data-action="moveexercise" data-ri="${ri}" data-ei="${ei}" data-delta="-1" aria-label="Subir ${esc(e.name)}" ${ei===0?'disabled':''}>↑</button><button class="textbtn" data-action="moveexercise" data-ri="${ri}" data-ei="${ei}" data-delta="1" aria-label="Bajar ${esc(e.name)}" ${ei===r.exercises.length-1?'disabled':''}>↓</button>${g?`<button class="textbtn" data-action="guide" data-ri="${ri}" data-ei="${ei}">Ver guía</button>`:''}<button class="textbtn" data-action="notes" data-id="${esc(e.id)}">Notas</button><button class="textbtn" data-action="removeexercise" data-ri="${ri}" data-ei="${ei}">Quitar</button></div></div>`;}).join('')||'<p class="note">Este día está vacío. Añade tu primer ejercicio para poder entrenar.</p>'}<button class="btn secondary full" data-action="addexercise" data-ri="${ri}" style="margin-top:16px">+ Añadir ejercicio</button></section>`).join('')||'<section class="card empty"><h2>Crea tu primer día.</h2><p>Puedes organizar los días y ejercicios a tu manera.</p><button class="btn" data-action="newroutine">Crear día de entrenamiento</button></section>'}</div><div class="stack">${renderSavedPlans()}<section class="card"><h2>Tu plan personal</h2><p class="note">Crea días, añade ejercicios del catálogo o registra uno personalizado. Usa las flechas para cambiar el orden.</p><p class="note">Los cambios de rutina se aplican a las próximas sesiones. El entrenamiento que ya has empezado conserva su contenido.</p><button class="btn secondary full" data-action="goal" style="margin-top:16px">Días y rutina · ${state.settings.weeklyGoal} / semana</button></section><section class="card"><h2>Tus datos, en tu móvil</h2><p class="note">Rutinas, ajustes, objetivos y entrenamientos se guardan en este dispositivo. Exporta una copia antes de cambiar de móvil o de navegador.</p><div class="actions"><button class="btn secondary" data-action="export">Exportar copia</button><button class="btn secondary" data-action="import">Importar</button></div><input type="file" accept="application/json,.json" id="import-file" hidden><button class="textbtn" data-action="reset" style="margin-top:14px">${loadError?'Reiniciar tras recuperar la copia':'Borrar todos los datos'}</button></section><section class="card"><h2>Entrena con control</h2><details class="help"><summary>Cómo seguir tu plan</summary><p>Las primeras dos semanas puedes usar el modo de adaptación: dos series por ejercicio. Calienta antes de empezar y deja 2–3 repeticiones en reserva.</p><p>Cuando completes el máximo del rango con buena técnica y margen, prueba el incremento mínimo disponible. Pide al monitor que te enseñe movimientos desconocidos y para ante dolor punzante o articular.</p><p>Plan general para adultos sin lesiones conocidas. <a href="https://acsm.org/resistance-training-guidelines-update-2026/" target="_blank" rel="noopener">Referencia: ACSM</a>.</p></details><p class="note">El temporizador se ajusta al volver; no emite una alarma con la pantalla bloqueada.</p></section></div></div>`;}
function renderHistory(){return pagehead('CADA SESIÓN CUENTA','Tu historial.')+`<section class="card">${state.history.length?state.history.map(s=>`<details class="historyitem"><summary><div class="section-title"><div><h3>${esc(s.name)}</h3><span class="small muted">${new Date(s.finished).toLocaleDateString('es-ES',{weekday:'long',day:'numeric',month:'long'})} · ${Math.max(1,Math.round((s.finished-s.started)/60000))} min</span></div><span class="pill">${completed(s)} series</span></div></summary><div class="detail">${recordCards(recordsFor(s))}${s.exercises.map(e=>`<div class="rule"><strong>${esc(e.name)}</strong><p>${e.logs.filter(l=>l.done).map(l=>`${num(l.kg)} kg × ${l.reps}`).join(' · ')}</p>${e.noteSnapshot?`<p class="history-note">Ajustes: ${esc(e.noteSnapshot)}</p>`:''}</div>`).join('')}<button class="textbtn" data-action="deletehistory" data-id="${esc(s.id)}">Eliminar sesión</button></div></details>`).join(''):'<div class="empty"><h2>El primer paso se registra aquí.</h2><p>Cuando termines un entrenamiento, verás tus ejercicios, pesos y repeticiones.</p><a class="btn" href="#entrenar">Ir a entrenar</a></div>'}</section>`;}
function renderProgress(){const catalog=new Map();state.routines.forEach(r=>r.exercises.forEach(e=>catalog.set(e.id,e.name)));state.history.forEach(s=>s.exercises.forEach(e=>catalog.set(e.id,e.name)));if(!catalog.has(progressId))progressId=catalog.keys().next().value;const records=state.history.slice().reverse().flatMap(s=>{const logs=s.exercises.filter(e=>e.id===progressId).flatMap(e=>e.logs.filter(l=>l.done));return logs.length?[{date:s.finished,kg:Math.max(...logs.map(l=>l.kg)),reps:logs.reduce((n,l)=>n+l.reps,0)}]:[];});let graph='';if(records.length>1){const vals=records.slice(-12),max=Math.max(...vals.map(v=>v.kg),1),min=Math.min(...vals.map(v=>v.kg)),lo=Math.max(0,min-(max-min||max)*.2),hi=max+(max-lo)*.15;const points=vals.map((v,i)=>[48+i/(vals.length-1)*500,190-(v.kg-lo)/(hi-lo)*150]);graph=`<svg class="chart" viewBox="0 0 600 240" role="img" aria-label="Evolución del peso máximo registrado por sesión"><path d="M48 25V190H560" fill="none" stroke="#dce2e6"/><text x="5" y="40">${num(hi)} kg</text><text x="5" y="193">${num(lo)}</text><polyline points="${points.map(p=>p.join(',')).join(' ')}" fill="none" stroke="#5b8415" stroke-width="3"/>${points.map((p,i)=>`<circle cx="${p[0]}" cy="${p[1]}" r="5" fill="#5b8415"><title>${fmtDate(vals[i].date)}: ${num(vals[i].kg)} kg</title></circle>`).join('')}<text x="48" y="223">${fmtDate(vals[0].date)}</text><text x="548" y="223" text-anchor="end">${fmtDate(vals.at(-1).date)}</text></svg>`;}
return pagehead('COMPITE CONTIGO','Tu progreso.')+`<div class="grid"><section class="card"><label for="exercise-progress" style="margin-top:0">Ejercicio</label><select id="exercise-progress">${[...catalog].map(([id,name])=>`<option value="${esc(id)}" ${id===progressId?'selected':''}>${esc(name)}</option>`).join('')}</select>${records.length?`<div class="statline" style="margin-top:24px"><div><strong>${num(Math.max(...records.map(r=>r.kg)))}<span> kg</span></strong><span>mayor peso registrado</span></div><div><strong>${records.length}</strong><span>sesiones</span></div></div>${graph||'<p class="note">Registra una segunda sesión de este ejercicio para ver la gráfica.</p>'}<p class="note">Peso máximo de cada sesión, sin estimar tu repetición máxima. Compara también las repeticiones y usa siempre la misma máquina o material.</p>${records.slice().reverse().slice(0,12).map(r=>`<div class="routine"><span class="grow">${fmtDate(r.date)}</span><strong>${num(r.kg)} kg</strong><span class="small muted">${r.reps} reps totales</span></div>`).join('')}`:`<div class="empty"><h3>Aquí empieza tu progreso.</h3><p>Completa una sesión con este ejercicio para ver tus marcas reales.</p></div>`}</section><div class="stack">${renderWeek()}${renderRecordsPanel()}<section class="card"><h2>No todo son kilos</h2><div class="rule"><strong>Más repeticiones</strong><p>Pasar de 8 a 10 repeticiones con el mismo peso también es progresar.</p></div><div class="rule"><strong>Mejor control</strong><p>Un movimiento estable y un recorrido cómodo importan más que subir peso deprisa.</p></div><div class="rule"><strong>Constancia</strong><p>Compara varias semanas. Un entrenamiento más flojo no borra lo que has conseguido.</p></div></section></div></div>`;}
function renderRecordsPanel(){const recent=state.history.slice(0,12).flatMap(s=>recordsFor(s).map(r=>({...r,date:s.finished}))).slice(0,6);return `<section class="card"><div class="section-title"><h2>Tus últimas mejoras</h2><span class="pill">Marcas reales</span></div>${recent.length?recordCards(recent):'<p class="note">Cuando superes un peso anterior o hagas más repeticiones con la misma carga, aparecerá aquí. La primera sesión establece tu referencia.</p>'}<p class="note">Compara el mismo ejercicio, material y técnica. Subir peso no es el único objetivo.</p></section>`;}
function modal(content){const d=$('#modal');d.classList.remove('guide-dialog');d.removeAttribute('aria-labelledby');$('#modal-body').innerHTML=content;if(!d.open)d.showModal();}
function close(){if($('#modal').open)$('#modal').close();}
function formActions(label='Guardar'){return `<div class="actions"><button type="button" class="btn secondary" data-action="close">Cancelar</button><button class="btn" type="submit">${label}</button></div>`;}
function confirmAction(title,body,action,label='Confirmar'){modal(`<h2>${esc(title)}</h2><p class="muted">${body}</p><div class="actions"><button class="btn secondary" data-action="close">Volver</button><button class="btn" data-action="${action}">${esc(label)}</button></div>`);}
function editRoutine(ri=null){if(ri===null&&state.routines.length>=20){toast('Puedes tener hasta 20 días de entrenamiento.');return;}routineEditing=ri;const r=ri===null?{name:'',day:'Sin día fijo',focus:'',optional:false}:state.routines[ri];modal(`<h2>${ri===null?'Crear día de entrenamiento':'Editar día'}</h2><form id="routine-form"><label for="routine-name">Nombre</label><input id="routine-name" name="name" value="${esc(r.name)}" placeholder="Ej.: Espalda y bíceps" required maxlength="120" class="full-input"><label for="routine-day">Día habitual</label><select id="routine-day" name="day">${DAYS.map(d=>`<option ${d===r.day?'selected':''}>${d}</option>`).join('')}</select><label for="routine-focus">Descripción o grupos musculares</label><input id="routine-focus" name="focus" value="${esc(r.focus)}" maxlength="160" placeholder="Ej.: Tirón" class="full-input"><label class="check-label"><input name="optional" type="checkbox" ${r.optional?'checked':''}> Sesión opcional</label>${formActions(ri===null?'Crear día':'Guardar cambios')}</form>${ri!==null?`<button class="textbtn danger-text" data-action="removeroutine" data-ri="${ri}" style="margin-top:16px">Eliminar este día</button>`:''}`);}
function exerciseForm(e,context){editing={...context,original:clone(e)};modal(`<h2>${context.kind==='new'?'Ejercicio personalizado':'Editar ejercicio'}</h2><form id="edit-form"><label for="editname">Nombre del ejercicio o variante</label><input id="editname" name="name" value="${esc(e.name)}" required maxlength="120" class="full-input" placeholder="Ej.: Press en máquina de la sala 2"><div class="fieldrow"><div><label for="editsets">Series</label><input id="editsets" name="sets" type="number" min="1" max="10" value="${e.sets}" required></div><div><label for="editmin">Reps mín.</label><input id="editmin" name="min" type="number" min="1" max="50" value="${e.min}" required></div><div><label for="editmax">Reps máx.</label><input id="editmax" name="max" type="number" min="1" max="50" value="${e.max}" required></div></div><label for="editrest">Descanso · segundos</label><input id="editrest" name="rest" type="number" min="15" max="600" step="1" value="${e.rest}" required><label for="editguide">Guía visual</label><select id="editguide" name="guideId"><option value="">Sin guía asignada</option>${Object.entries(window.GYM_GUIDES).map(([id,g])=>`<option value="${id}" ${(e.guideId??e.id)===id?'selected':''}>${esc(g.title)}</option>`).join('')}</select><p class="note">Elige la guía que corresponda al movimiento. Cambiar el nombre crea una variante con marcas separadas.</p><label for="exercise-note">Ajustes de la máquina</label><textarea id="exercise-note" name="note" rows="3" maxlength="1000" placeholder="Asiento en el 4, agarre estrecho…">${esc(noteFor(e.id))}</textarea>${formActions(context.mode==='replace'?'Continuar':'Guardar')}</form>`);}
function showNotes(id){const e=exerciseCatalog().find(e=>e.id===id);if(!e)return;noteEditing=id;modal(`<h2>Ajustes de la máquina</h2><p class="muted">${esc(e.name)}</p><form id="notes-form"><label for="machine-note">Tu nota</label><textarea id="machine-note" name="note" rows="5" maxlength="1000" placeholder="Asiento en el 4. Respaldo en el 2. Agarre estrecho.">${esc(noteFor(id))}</textarea><p class="note">La recordarás cada vez que entrenes este ejercicio. Para otra máquina con marcas diferentes, crea una variante.</p>${formActions()}</form>`);}
function showPicker(context){picker={...context,query:'',group:'Todos',chosen:null};if(picker.mode==='add'&&state.routines[picker.ri].exercises.length>=30){toast('Este día ya tiene 30 ejercicios.');return;}modal(`<h2>${picker.mode==='replace'?'Cambiar ejercicio':'Añadir ejercicio'}</h2>${picker.mode==='replace'?'<p class="note">Elige una alternativa adecuada para ti. Los grupos musculares te ayudan a buscar; no todas las opciones son equivalentes.</p>':''}<label for="catalog-search">Buscar ejercicio</label><input id="catalog-search" type="search" placeholder="Nombre del ejercicio…" autocomplete="off" class="full-input"><label for="catalog-group">Grupo muscular</label><select id="catalog-group">${['Todos','Pecho','Espalda','Piernas','Hombros','Brazos','Abdomen','Personalizados'].map(g=>`<option>${g}</option>`).join('')}</select><div id="catalog-results" class="catalog-results"></div><div class="actions"><button class="btn secondary" data-action="close">Volver</button><button class="btn" data-action="customexercise">+ Personalizado</button></div>`);renderPickerResults();}
function renderPickerResults(){if(!picker)return;const fold=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase(),old=picker.mode==='replace'?state.active.exercises[picker.index]:null;let list=exerciseCatalog().filter(e=>e.id!==old?.id&&(picker.group==='Todos'||groupFor(e)===picker.group)&&fold(e.name+' '+groupFor(e)).includes(fold(picker.query)));if(old)list.sort((a,b)=>(groupFor(b)===groupFor(old))-(groupFor(a)===groupFor(old)));$('#catalog-results').innerHTML=list.map(e=>{const g=getGuide(e);return `<button class="catalog-item" data-action="chooseexercise" data-id="${esc(e.id)}">${g?`<img src="./assets/exercises/${g.art}-1.svg" alt="" width="55" height="55" loading="lazy">`:'<span class="custom-exercise-icon" aria-hidden="true">+</span>'}<span><strong>${esc(e.name)}</strong><small>${esc(groupFor(e))} · ${e.sets} × ${e.min}–${e.max}</small></span><span aria-hidden="true">+</span></button>`;}).join('')||'<p class="note">No hay coincidencias. Puedes crear un ejercicio personalizado.</p>';}
function chooseExercise(target,noteDraft){if(picker.mode==='replace'){picker.chosen=clone(target);picker.noteDraft=noteDraft;showReplacement();return;}const ri=picker.ri;if(!state.routines[ri]||state.routines[ri].exercises.length>=30)return;if(commit(()=>{state.routines[ri].exercises.push({...clone(target),slotId:uid()});if(noteDraft!==undefined)putNote(target.id,noteDraft);})){close();go('rutina');document.getElementById('routine-'+ri)?.scrollIntoView({block:'start'});toast('Ejercicio añadido. Puedes editar las series y repeticiones.');}}
function permanentSlot(old){const r=state.routines.find(r=>r.id===state.active?.routineId);const i=r?.exercises.findIndex(e=>e.slotId===old.slotId&&e.id===(old.originExerciseId||old.id));return r&&i>=0?{r,i}:null;}
function showReplacement(){const old=state.active.exercises[picker.index],target=picker.chosen,done=old.logs.filter(l=>l.done).length,pending=old.logs.length-done;modal(`<h2>${esc(target.name)}</h2><p class="muted">Sustituye a ${esc(old.name)}.</p><p class="note">${done?`Se conservarán las ${done} series completadas del ejercicio anterior. `:''}La alternativa tendrá ${pending} series pendientes con peso y repeticiones en blanco, y un rango de ${target.min}–${target.max} reps.</p><form id="replace-form"><label class="check-label"><input type="radio" name="scope" value="today" checked> Solo para esta sesión</label><label class="check-label"><input type="radio" name="scope" value="permanent" ${permanentSlot(old)?'':'disabled'}> También cambiarlo en esta rutina</label>${!permanentSlot(old)?'<p class="note">La rutina original ha cambiado o se eliminó. Puedes sustituirlo solo para hoy.</p>':''}<p class="note">Cada ejercicio conserva sus propias marcas. Los valores pendientes del anterior se reiniciarán.</p>${formActions('Cambiar ejercicio')}</form>`);}
function applyReplacement(permanent){
 const s=state.active,old=s?.exercises[picker?.index],target=picker?.chosen;if(!old||!target||old.id===target.id)return false;
 const made=old.logs.filter(l=>l.done),left=old.logs.length-made.length;
 if(!left){toast('Ya has completado todas las series de este ejercicio.');return false;}
 if(made.length&&s.exercises.length>=60){toast('La sesión ha alcanzado el límite de ejercicios.');return false;}
 const slot=permanent?permanentSlot(old):null;if(permanent&&!slot){toast('La rutina ha cambiado. Elige solo para esta sesión.');return false;}
 const index=picker.index;
 if(!commit(()=>{
   const replacement={...clone(target),slotId:old.slotId,originExerciseId:permanent?target.id:old.originExerciseId||old.id,swappedFrom:old.name,logs:Array.from({length:left},blankLog)};
   if(made.length){s.exercises.splice(index,1,{...old,logs:made,retained:true},replacement);s.focusIndex=index+1;}else{s.exercises.splice(index,1,replacement);s.focusIndex=index;}
   if(slot)slot.r.exercises[slot.i]={...clone(target),slotId:old.slotId};
   if(picker.noteDraft!==undefined)putNote(target.id,picker.noteDraft);
 }))return false;
 close();render();toast(permanent?'Ejercicio cambiado para hoy y para esta rutina.':'Ejercicio cambiado solo para esta sesión.');return true;
}
function startSession(adapt){const r=state.routines.find(r=>r.id===selected);if(!r?.exercises.length){toast('Añade ejercicios a este día antes de empezar.');return;}if(commit(()=>{state.active={id:uid(),routineId:r.id,name:r.name,started:Date.now(),focusIndex:0,exercises:r.exercises.map(e=>({...clone(e),originExerciseId:e.id,logs:Array.from({length:adapt?Math.min(2,e.sets):e.sets},blankLog)}))};state.timerEnd=null;})){close();go('entrenar');}}
function timerMarkup(){if(!state.timerEnd)return '<p class="eyebrow">DESCANSO</p><p class="small muted">El temporizador empieza al completar una serie.</p>';const sec=Math.max(0,Math.ceil((state.timerEnd-Date.now())/1000));return `<div class="timerrow"><div><div class="small">${sec?'Descanso':'Descanso terminado'}</div><strong>${Math.floor(sec/60)}:${String(sec%60).padStart(2,'0')}</strong></div><button data-action="timerplus" aria-label="Añadir 30 segundos">+30 s</button><button data-action="timerstop" aria-label="Cerrar temporizador">✕</button></div>`;}
function renderTimer(){const inline=$('#focus-timer'),el=$('#timer');if(inline)inline.innerHTML=timerMarkup();el.hidden=!state.timerEnd||!!inline;if(!el.hidden)el.innerHTML=timerMarkup();}
function startTimer(seconds){if(commit(()=>state.timerEnd=Date.now()+seconds*1000))renderTimer();}
function updateSessionCounts(){if(!state.active)return;const s=state.active,total=s.exercises.reduce((n,e)=>n+e.logs.length,0);if($('#session-count'))$('#session-count').textContent=`${completed(s)} / ${total} series`;if($('#session-progress'))$('#session-progress').style.width=completed(s)/total*100+'%';s.exercises.forEach((e,i)=>{const node=$(`[data-count="${i}"]`);if(node)node.textContent=`${e.logs.filter(l=>l.done).length} / ${e.logs.length} series completadas`;const change=$(`[data-action="replace"][data-ex="${i}"]`);if(change)change.disabled=!!e.retained||e.logs.every(l=>l.done);});}
function inputIsValid(){const invalid=$('input[data-field]:invalid');if(invalid){invalid.reportValidity();return false;}return true;}
function finishSession(){if(!state.active||!completed(state.active))return;const finished=clone(state.active);finished.finished=Date.now();finished.exercises.forEach(e=>{e.logs=e.logs.filter(l=>l.done);e.noteSnapshot=noteFor(e.id);});finished.exercises=finished.exercises.filter(e=>e.logs.length);delete finished.focusIndex;const records=recordsFor(finished);if(!commit(()=>{state.history.unshift(finished);state.active=null;state.timerEnd=null;}))return;selected=nextRoutine();close();go('historial');modal(`<p class="eyebrow">ENTRENAMIENTO GUARDADO</p><h2>${completed(finished)} series que cuentan.</h2><p class="muted">${esc(finished.name)} · ${weeklyStats().sessions.length} / ${state.settings.weeklyGoal} sesiones esta semana.</p>${records.length?`<div class="finish-records">${recordCards(records)}</div>`:'<p class="note">Tus marcas quedan guardadas para la próxima sesión.</p>'}<button class="btn lime full" data-action="close" style="margin-top:20px">Ver historial</button>`);}
function restoreData(data){const before=state,wasError=loadError;state=normalizeState(data);loadError=false;if(!save()){state=before;loadError=wasError;return false;}selected=state.active?.routineId||nextRoutine();return true;}
function exportData(){const raw=loadError?localStorage.getItem(KEY):JSON.stringify(state,null,2),blob=new Blob([raw||''],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`mi-gym-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}

document.addEventListener('click',ev=>{
 const b=ev.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,d=b.dataset;
 if(a==='close'){close();return;}
 if(a==='guidetab'){changeGuideTab(d.tab);return;}
 if(['navigate','mode','guide','notes','replace','finish','selectplan'].includes(a)&&!inputIsValid())return;
 if(a==='guide'){const e=d.ri!==undefined?state.routines[+d.ri]?.exercises[+d.ei]:state.active?.exercises[+d.ex];if(e)showGuide(e);return;}
 if(a==='select'){selected=d.id;render();return;}
 if(a==='selectplan'){selected=d.id;go('entrenar');return;}
 if(a==='newroutine'){editRoutine();return;}
 if(a==='editroutine'){editRoutine(+d.ri);return;}
 if(a==='goal'){showGoal();return;}
 if(a==='restoreplan'){const p=state.savedPlans[+d.index];if(!p)return;pendingPlanId=p.id;confirmAction('¿Recuperar este plan?',`${esc(p.name)} sustituirá la distribución actual. El historial, las notas y la sesión en curso se conservan. Si tu rutina actual está personalizada, también quedará guardada.`,'restoreplanconfirmed','Recuperar plan');return;}
 if(a==='restoreplanconfirmed'){restoreSavedPlan(pendingPlanId);return;}
 if(a==='deleteplan'){pendingPlanDelete=d.id;confirmAction('¿Eliminar esta copia?','Solo se eliminará esta copia de la rutina. El plan actual y los entrenamientos guardados se conservan.','deleteplanconfirmed','Eliminar copia');return;}
 if(a==='deleteplanconfirmed'){if(commit(()=>state.savedPlans=state.savedPlans.filter(p=>p.id!==pendingPlanDelete))){close();render();}return;}
 if(a==='notes'){showNotes(d.id);return;}
 if(a==='moveroutine'||a==='moveexercise'){const list=a==='moveroutine'?state.routines:state.routines[+d.ri].exercises,i=a==='moveroutine'?+d.ri:+d.ei,j=i+(+d.delta);if(j<0||j>=list.length)return;if(commit(()=>{[list[i],list[j]]=[list[j],list[i]];}))render();return;}
 if(a==='removeroutine'||a==='removeexercise'){pendingRemove={kind:a,ri:+d.ri,ei:+d.ei};const r=state.routines[+d.ri];confirmAction(a==='removeroutine'?'¿Eliminar este día?':'¿Quitar este ejercicio?',`${esc(a==='removeroutine'?r.name:r.exercises[+d.ei].name)} se quitará de tu plan. El historial y la sesión en curso se conservan.`,'removeconfirmed','Eliminar');return;}
 if(a==='removeconfirmed'&&pendingRemove){if(commit(()=>{if(pendingRemove.kind==='removeroutine')state.routines.splice(pendingRemove.ri,1);else state.routines[pendingRemove.ri].exercises.splice(pendingRemove.ei,1);})){selected=nextRoutine();pendingRemove=null;close();render();}return;}
 if(a==='addexercise'){showPicker({mode:'add',ri:+d.ri});return;}
 if(a==='replace'){showPicker({mode:'replace',index:+d.ex});return;}
 if(a==='chooseexercise'){const target=exerciseCatalog().find(e=>e.id===d.id);if(target)chooseExercise(target);return;}
 if(a==='customexercise'){exerciseForm({id:'custom-'+uid(),name:'',sets:3,min:8,max:12,rest:90,cue:'Pide al monitor que te enseñe la técnica y adapta la carga a tu nivel.',alt:'Consulta una alternativa adecuada con el monitor',guideId:''},{kind:'new',mode:picker.mode,ri:picker.ri});return;}
 if(a==='edit'){const ri=+d.ri,ei=+d.ei;exerciseForm(state.routines[ri].exercises[ei],{kind:'edit',ri,ei});return;}
 if(a==='start'){if(loadError){toast('Revisa tus datos en Rutina antes de entrenar.');return;}if(state.active){go('entrenar');return;}selected=d.id;modal('<h2>¿Cómo entrenas hoy?</h2><p class="muted">Al empezar o retomar puedes elegir dos series por ejercicio.</p><div class="actions"><button class="btn lime" data-action="startadapt">Adaptación · 2 series</button><button class="btn" data-action="startnormal">Series del plan</button></div><button class="textbtn" data-action="close">Volver</button>');return;}
 if(a==='startadapt'||a==='startnormal'){startSession(a==='startadapt');return;}
 if(a==='mode'){if(commit(()=>state.settings.trainingMode=d.mode==='list'?'list':'focus'))render();return;}
 if(a==='navigate'){const i=+d.index;if(state.active&&integer(i,0,state.active.exercises.length-1)&&commit(()=>state.active.focusIndex=i)){render();window.scrollTo(0,0);}return;}
 if(a==='rest'){startTimer(+d.seconds);return;}
 if(a==='timerplus'){if(commit(()=>state.timerEnd=Math.max(Date.now(),state.timerEnd||Date.now())+30000))renderTimer();return;}
 if(a==='timerstop'){if(commit(()=>state.timerEnd=null))renderTimer();return;}
 if(a==='check'){if(!inputIsValid())return;const e=state.active?.exercises[+d.ex],l=e?.logs[+d.set];if(!l)return;if(!l.done&&(l.kg===''||l.reps==='')){toast('Escribe el peso y las repeticiones. Usa 0 kg si no hay carga.');return;}if(commit(()=>{l.done=!l.done;if(l.done)state.timerEnd=Date.now()+e.rest*1000;})){render();if(e.logs.every(l=>l.done))toast('Ejercicio completado. Descansa y pasa al siguiente cuando quieras.');}return;}
 if(a==='addset'||a==='removeset'){if(!inputIsValid())return;const e=state.active?.exercises[+d.ex];if(!e||e.retained)return;if(a==='removeset'&&e.logs.at(-1).done){toast('Desmarca la última serie antes de quitarla.');return;}if(commit(()=>{if(a==='addset'&&e.logs.length<15)e.logs.push(blankLog());if(a==='removeset'&&e.logs.length>1)e.logs.pop();}))render();return;}
 if(a==='finish'){if(!state.active)return;const n=completed(state.active);if(!n){toast('Completa al menos una serie antes de guardar.');return;}confirmAction('¿Guardar entrenamiento?',`Guardarás ${n} series completadas. Las series sin marcar no se incluirán en el historial.`,'finishconfirmed','Guardar sesión');return;}
 if(a==='finishconfirmed'){finishSession();return;}
 if(a==='cancel'){confirmAction('¿Descartar esta sesión?','Se eliminará el entrenamiento en curso. Las sesiones anteriores seguirán guardadas.','cancelconfirmed','Descartar');return;}
 if(a==='cancelconfirmed'){if(commit(()=>{state.active=null;state.timerEnd=null;})){close();render();}return;}
 if(a==='deletehistory'){pendingDelete=d.id;confirmAction('¿Eliminar esta sesión?','Se quitará del historial, de los récords y del objetivo semanal.','deleteconfirmed','Eliminar');return;}
 if(a==='deleteconfirmed'){if(commit(()=>state.history=state.history.filter(s=>s.id!==pendingDelete))){close();render();}return;}
 if(a==='export'){exportData();return;}
 if(a==='import'){$('#import-file').click();return;}
 if(a==='importconfirmed'&&imported){if(restoreData(imported)){imported=null;close();render();toast('Copia restaurada.');}return;}
 if(a==='reset'){confirmAction('¿Borrar todos los datos?','Se borrarán el historial, la sesión, las notas, las rutinas y las copias de planes anteriores. Exporta antes una copia si quieres conservarlos.','resetconfirmed','Borrar todo');return;}
 if(a==='resetconfirmed'){if(restoreData(freshState())){close();render();}return;}
});
document.addEventListener('keydown',ev=>{if(!ev.target.closest('[data-action=guidetab]')||!['ArrowLeft','ArrowRight','Home','End'].includes(ev.key))return;ev.preventDefault();changeGuideTab(ev.key==='Home'?'muscles':ev.key==='End'?'movement':guideTab==='muscles'?'movement':'muscles');});
document.addEventListener('input',ev=>{
 const el=ev.target;
 if(el.id==='catalog-search'){picker.query=el.value;renderPickerResults();return;}
 if(!el.dataset.field||!state.active)return;const field=el.dataset.field;if(!['kg','reps'].includes(field))return;const e=state.active.exercises[+el.dataset.ex],l=e.logs[+el.dataset.set],n=el.value===''?'':Number(el.value);
 if(el.validity.badInput||(n!==''&&(!Number.isFinite(n)||n<0||n>(field==='kg'?2000:200)||(field==='reps'&&!integer(n,1,200))))){el.setCustomValidity('Introduce un valor válido.');return;}
 el.setCustomValidity('');const wasDone=l.done;if(commit(()=>{l[field]=n;if(wasDone)l.done=false;})){if(wasDone){const row=el.closest('.set');row.classList.remove('done');const button=row.querySelector('button');button.textContent='○';button.setAttribute('aria-pressed','false');button.setAttribute('aria-label',`Completar serie ${+el.dataset.set+1} de ${e.name}`);}updateSessionCounts();}
});
document.addEventListener('change',ev=>{const el=ev.target;if(el.id==='weekly-goal'){renderPlanPreview(+el.value);return;}if(el.dataset.field&&!el.validity.valid)el.reportValidity();if(el.id==='catalog-group'){picker.group=el.value;renderPickerResults();}if(el.id==='exercise-progress'){progressId=el.value;render();}if(el.id==='session-jump'&&el.value!==''){if(!inputIsValid())return;const i=+el.value;if(integer(i,0,state.active.exercises.length-1)&&commit(()=>{state.active.focusIndex=i;state.settings.trainingMode='focus';})){render();window.scrollTo(0,0);}}if(el.id==='import-file'){const file=el.files[0];if(!file)return;if(file.size>5e6){toast('La copia supera el límite de 5 MB.');return;}file.text().then(raw=>{try{const data=JSON.parse(raw);if(!validState(data))throw Error();imported=data;confirmAction('¿Restaurar esta copia?',`Contiene ${data.routines.length} días y ${data.history.length} sesiones. Sustituirá los datos actuales de esta app.`,'importconfirmed','Restaurar');}catch{toast('El archivo no es una copia válida de Mi Gym.');}}).catch(()=>toast('No se pudo leer el archivo.'));}});
document.addEventListener('submit',ev=>{
 const form=ev.target;if(!['routine-form','edit-form','goal-form','notes-form','replace-form'].includes(form.id))return;ev.preventDefault();if(!form.reportValidity())return;const f=new FormData(form);
 if(form.id==='routine-form'){const name=f.get('name').trim(),focus=f.get('focus').trim(),day=f.get('day'),optional=f.get('optional')==='on';if(!name||!DAYS.includes(day))return;if(commit(()=>{if(routineEditing===null)state.routines.push({id:'routine-'+uid(),name,focus,day,optional,exercises:[]});else Object.assign(state.routines[routineEditing],{name,focus,day,optional});})){close();go('rutina');if(routineEditing===null)showPicker({mode:'add',ri:state.routines.length-1});else document.getElementById('routine-'+routineEditing)?.scrollIntoView({block:'start'});toast('Día guardado.');}return;}
 if(form.id==='goal-form'){applyTrainingDays(+f.get('goal'));return;}
 if(form.id==='notes-form'){const text=f.get('note').trim();if(text.length<=1000&&commit(()=>putNote(noteEditing,text))){close();render();toast('Ajustes guardados para este ejercicio.');}return;}
 if(form.id==='replace-form'){applyReplacement(f.get('scope')==='permanent');return;}
 if(form.id==='edit-form'){
   const name=f.get('name').trim(),min=+f.get('min'),max=+f.get('max'),note=f.get('note').trim(),old=editing.original;
   const target={...clone(old),name,sets:+f.get('sets'),min,max,rest:+f.get('rest'),guideId:Object.prototype.hasOwnProperty.call(window.GYM_GUIDES,f.get('guideId'))?f.get('guideId'):''};
   if(editing.kind==='edit'&&name!==old.name){target.id='custom-'+uid();target.cue='Pide al monitor que te enseñe la técnica y adapta la carga a tu nivel.';target.alt='Consulta una alternativa adecuada con el monitor';}
   if(!validExercise(target)||note.length>1000){toast('Revisa el nombre, las series y el rango de repeticiones.');return;}
   if(editing.kind==='new'){chooseExercise(target,note);return;}
   if(commit(()=>{state.routines[editing.ri].exercises[editing.ei]=target;putNote(target.id,note);})){close();render();toast('Ejercicio actualizado para las próximas sesiones.');}
 }
});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);});
window.addEventListener('pageshow',()=>renderTimer());setInterval(renderTimer,1000);render();
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
